package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Nothing is silently defaulted. A missing file, an unknown key, or a value that is empty or malformed makes
 * loading fail. Every problem found is reported together in one {@link ConfigException}. A key that is absent
 * takes its documented default.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");
    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url", "api.token", "worker.threads", "queue.capacity",
            "retry.max-attempts", "request.timeout", "metrics.enabled");

    private ConfigLoader() {}

    /**
     * @throws ConfigException if the file cannot be read or any setting is wrong; the message lists every problem
     */
    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();

        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add("unknown key '" + key + "'");
            }
        }
        URI upstream = upstream(properties, problems);
        String apiToken = required(properties, "api.token", problems);
        int workerThreads = intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = duration(properties, problems);
        boolean metricsEnabled = flag(properties, "metrics.enabled", false, problems);

        if (!problems.isEmpty()) {
            throw new ConfigException(message(file, problems));
        }
        return new ServiceConfig(
                upstream, apiToken, workerThreads, queueCapacity, retryAttempts, requestTimeout, metricsEnabled);
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (NoSuchFileException e) {
            throw new ConfigException("configuration file not found: " + file);
        } catch (IOException e) {
            throw new ConfigException("cannot read configuration file " + file + ": " + e.getMessage());
        } catch (IllegalArgumentException e) {
            throw new ConfigException("configuration file " + file + " is malformed: " + e.getMessage());
        }
        return properties;
    }

    private static String message(Path file, List<String> problems) {
        StringBuilder message = new StringBuilder("invalid configuration in " + file + ":");
        for (String problem : problems) {
            message.append("\n  - ").append(problem);
        }
        return message.toString();
    }

    /** The trimmed value of a key that is present, or null if it is absent or empty (empty is a problem). */
    private static String present(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return null;
        }
        String value = raw.trim();
        if (value.isEmpty()) {
            problems.add(key + " must not be empty");
            return null;
        }
        return value;
    }

    private static String required(Properties properties, String key, List<String> problems) {
        if (properties.getProperty(key) == null) {
            problems.add(key + " is required");
            return null;
        }
        return present(properties, key, problems);
    }

    private static URI upstream(Properties properties, List<String> problems) {
        String raw = required(properties, "upstream.url", problems);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            String scheme = uri.getScheme();
            if (uri.isAbsolute() && uri.getHost() != null
                    && ("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))) {
                return uri;
            }
        } catch (URISyntaxException e) {
            // reported below
        }
        problems.add("upstream.url must be an absolute http or https URL, got '" + raw + "'");
        return null;
    }

    private static int intValue(
            Properties properties, String key, int defaultValue, int minimum, List<String> problems) {
        if (properties.getProperty(key) == null) {
            return defaultValue;
        }
        String raw = present(properties, key, problems);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw);
            if (value >= minimum) {
                return value;
            }
        } catch (NumberFormatException e) {
            // reported below
        }
        problems.add(key + " must be a whole number of at least " + minimum + ", got '" + raw + "'");
        return defaultValue;
    }

    private static Duration duration(Properties properties, List<String> problems) {
        String key = "request.timeout";
        if (properties.getProperty(key) == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        String raw = present(properties, key, problems);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Matcher matcher = DURATION.matcher(raw);
        if (matcher.matches()) {
            try {
                long amount = Long.parseLong(matcher.group(1));
                return switch (matcher.group(2)) {
                    case "ms" -> Duration.ofMillis(amount);
                    case "s" -> Duration.ofSeconds(amount);
                    default -> Duration.ofMinutes(amount);
                };
            } catch (ArithmeticException | NumberFormatException e) {
                // reported below
            }
        }
        problems.add(key + " must be a whole number followed by ms, s or m, e.g. 30s, got '" + raw + "'");
        return DEFAULT_REQUEST_TIMEOUT;
    }

    private static boolean flag(Properties properties, String key, boolean defaultValue, List<String> problems) {
        if (properties.getProperty(key) == null) {
            return defaultValue;
        }
        String raw = present(properties, key, problems);
        if (raw == null) {
            return defaultValue;
        }
        if (raw.equalsIgnoreCase("true")) {
            return true;
        }
        if (raw.equalsIgnoreCase("false")) {
            return false;
        }
        problems.add(key + " must be true or false, got '" + raw + "'");
        return defaultValue;
    }
}

