package com.acme.relay.config;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ConfigLoaderTest {
    private static final String REQUIRED = """
            upstream.url=https://uplink.example.com/v1/events
            api.token=s3cret
            """;

    @TempDir
    Path dir;

    @Test
    void loadsEveryKey() throws IOException {
        Path file = write(REQUIRED + """
                worker.threads=8
                queue.capacity=250
                retry.max-attempts=5
                request.timeout=2m
                metrics.enabled=true
                """);

        ServiceConfig config = ConfigLoader.load(file);

        assertEquals(URI.create("https://uplink.example.com/v1/events"), config.upstream());
        assertEquals("s3cret", config.apiToken());
        assertEquals(8, config.workerThreads());
        assertEquals(250, config.queueCapacity());
        assertEquals(5, config.retryAttempts());
        assertEquals(Duration.ofMinutes(2), config.requestTimeout());
        assertTrue(config.metricsEnabled());
    }

    @Test
    void optionalKeysUseTheirDefaults() throws IOException {
        ServiceConfig config = ConfigLoader.load(write(REQUIRED));

        assertEquals(ConfigLoader.DEFAULT_WORKER_THREADS, config.workerThreads());
        assertEquals(ConfigLoader.DEFAULT_QUEUE_CAPACITY, config.queueCapacity());
        assertEquals(ConfigLoader.DEFAULT_RETRY_ATTEMPTS, config.retryAttempts());
        assertEquals(ConfigLoader.DEFAULT_REQUEST_TIMEOUT, config.requestTimeout());
        assertFalse(config.metricsEnabled());
    }

    @Test
    void parsesAllTimeoutUnits() throws IOException {
        assertEquals(
                Duration.ofMillis(500),
                ConfigLoader.load(write(REQUIRED + "request.timeout=500ms\n")).requestTimeout());
        assertEquals(
                Duration.ofSeconds(45),
                ConfigLoader.load(write(REQUIRED + "request.timeout=45s\n")).requestTimeout());
    }

    @Test
    void apiTokenIsRequired() throws IOException {
        Path file = write("upstream.url=https://uplink.example.com/v1/events\n");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        assertTrue(error.getMessage().contains("api.token is required"));
    }

    @Test
    void rejectsWorkerCountThatIsNotANumber() throws IOException {
        assertRejected(REQUIRED + "worker.threads=four\n", "worker.threads", "'four'");
    }

    @Test
    void rejectsWorkerCountThatIsTypedWithALetterAtTheEnd() throws IOException {
        assertRejected(REQUIRED + "worker.threads=8x\n", "worker.threads", "'8x'");
    }

    @Test
    void rejectsZeroWorkers() throws IOException {
        assertRejected(REQUIRED + "worker.threads=0\n", "worker.threads", "at least 1", "'0'");
    }

    @Test
    void rejectsNegativeRetries() throws IOException {
        assertRejected(REQUIRED + "retry.max-attempts=-1\n", "retry.max-attempts", "'-1'");
    }

    @Test
    void rejectsQueueCapacityThatIsNotANumber() throws IOException {
        assertRejected(REQUIRED + "queue.capacity=lots\n", "queue.capacity", "'lots'");
    }

    @Test
    void rejectsTimeoutWithoutUnit() throws IOException {
        assertRejected(REQUIRED + "request.timeout=30\n", "request.timeout", "'30'");
    }

    @Test
    void rejectsTimeoutWithUnknownUnit() throws IOException {
        assertRejected(REQUIRED + "request.timeout=30h\n", "request.timeout", "'30h'");
    }

    @Test
    void rejectsMetricsValueThatIsNotBoolean() throws IOException {
        assertRejected(REQUIRED + "metrics.enabled=yes\n", "metrics.enabled", "'yes'");
    }

    @Test
    void rejectsUpstreamThatIsNotAHttpUrl() throws IOException {
        assertRejected("upstream.url=not a url\napi.token=s3cret\n", "upstream.url", "'not a url'");
        assertRejected("upstream.url=ftp://uplink.example.com/x\napi.token=s3cret\n", "upstream.url", "ftp://");
        assertRejected("upstream.url=/just/a/path\napi.token=s3cret\n", "upstream.url", "/just/a/path");
    }

    @Test
    void rejectsUnknownKeyThatWouldOtherwiseBeIgnored() throws IOException {
        assertRejected(REQUIRED + "worker.thread=8\n", "unknown key 'worker.thread'");
    }

    @Test
    void rejectsEmptyValueOfAnOptionalKey() throws IOException {
        assertRejected(REQUIRED + "queue.capacity=\n", "queue.capacity must not be empty");
    }

    @Test
    void rejectsMissingFileInsteadOfRunningOnDefaults() {
        Path missing = dir.resolve("does-not-exist.properties");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(missing));

        assertTrue(error.getMessage().contains("not found"), error.getMessage());
        assertTrue(error.getMessage().contains("does-not-exist.properties"), error.getMessage());
    }

    @Test
    void reportsEveryProblemAtOnce() throws IOException {
        Path file = write("""
                upstream.url=https://uplink.example.com/v1/events
                worker.threads=four
                metrics.enabled=yes
                """);

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        assertTrue(error.getMessage().contains("api.token is required"), error.getMessage());
        assertTrue(error.getMessage().contains("worker.threads"), error.getMessage());
        assertTrue(error.getMessage().contains("metrics.enabled"), error.getMessage());
    }

    private void assertRejected(String content, String... fragments) throws IOException {
        Path file = write(content);

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        for (String fragment : fragments) {
            assertTrue(error.getMessage().contains(fragment), "missing '" + fragment + "' in: " + error.getMessage());
        }
    }

    private Path write(String content) throws IOException {
        return Files.writeString(dir.resolve("config.properties"), content);
    }
}

