        assertRejected(REQUIRED + "retry.max-attempts=-1\n", "retry.max-attempts", "'-1'");
    }

    @Test
    void rejectsQueueCapacityThatIsNotANumber() throws IOException {
        assertRejected(REQUIRED + "queue.capacity=lots\n", "queue.capacity", "'lots'");
    }

    @Test
    void rejectsTimeoutWithoutUnit() throws IOException {
        assertRejected(REQUIRED + "request.timeout=30\n", "request.timeout", "'30'");
    }

    @Test
    void rejectsTimeoutWithUnknownUnit() throws IOException {
        assertRejected(REQUIRED + "request.timeout=30h\n", "request.timeout", "'30h'");
    }

    @Test
    void rejectsMetricsValueThatIsNotBoolean() throws IOException {
        assertRejected(REQUIRED + "metrics.enabled=yes\n", "metrics.enabled", "'yes'");
    }

    @Test
    void rejectsUpstreamThatIsNotAHttpUrl() throws IOException {
        assertRejected("upstream.url=not a url\napi.token=s3cret\n", "upstream.url", "'not a url'");
        assertRejected("upstream.url=ftp://uplink.example.com/x\napi.token=s3cret\n", "upstream.url", "ftp://");
        assertRejected("upstream.url=/just/a/path\napi.token=s3cret\n", "upstream.url", "/just/a/path");
    }

    @Test
    void rejectsUnknownKeyThatWouldOtherwiseBeIgnored() throws IOException {
        assertRejected(REQUIRED + "worker.thread=8\n", "unknown key 'worker.thread'");
    }

    @Test
    void rejectsEmptyValueOfAnOptionalKey() throws IOException {
        assertRejected(REQUIRED + "queue.capacity=\n", "queue.capacity must not be empty");
    }

    @Test
    void rejectsMissingFileInsteadOfRunningOnDefaults() {
        Path missing = dir.resolve("does-not-exist.properties");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(missing));

        assertTrue(error.getMessage().contains("not found"), error.getMessage());
        assertTrue(error.getMessage().contains("does-not-exist.properties"), error.getMessage());
    }

    @Test
    void reportsEveryProblemAtOnce() throws IOException {
        Path file = write("""
                upstream.url=https://uplink.example.com/v1/events
                worker.threads=four
                metrics.enabled=yes
                """);

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        assertTrue(error.getMessage().contains("api.token is required"), error.getMessage());
        assertTrue(error.getMessage().contains("worker.threads"), error.getMessage());
        assertTrue(error.getMessage().contains("metrics.enabled"), error.getMessage());
    }

    private void assertRejected(String content, String... fragments) throws IOException {
        Path file = write(content);

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        for (String fragment : fragments) {
            assertTrue(error.getMessage().contains(fragment), "missing '" + fragment + "' in: " + error.getMessage());
        }
    }

    private Path write(String content) throws IOException {
        return Files.writeString(dir.resolve("config.properties"), content);
    }
}

